import { z } from "zod";

/**
 * Public, immutable build-time configuration for a desktop preview installer.
 *
 * One validated manifest (see `desktopPreviewManifestSchema`) is generated by
 * the preview provisioning tooling, committed to the build as
 * `POSTHOG_DESKTOP_PREVIEW_CONFIG`, and baked into the Electron main and
 * renderer bundles at build time. It carries only public data: the backend
 * origin, the OAuth client id, the PR identity, and feature-flag overrides.
 * Credentials, provider keys, and signing material never appear here.
 *
 * A build is a preview build if and only if a valid manifest was supplied;
 * an ordinary release build must reject one (see `assertNoPreviewConfig`).
 */

export const DESKTOP_PREVIEW_SCHEMA_VERSION = 1;

const httpsOrigin = z
  .string()
  .url()
  .refine((value) => {
    let url: URL;
    try {
      url = new URL(value);
    } catch {
      return false;
    }
    return (
      url.protocol === "https:" &&
      !url.username &&
      !url.password &&
      url.pathname === "/" &&
      !url.search &&
      !url.hash
    );
  }, "backendOrigin must be a credential-free HTTPS origin")
  .transform((value) => new URL(value).origin);

const commitSha = z
  .string()
  .regex(/^[0-9a-f]{40}$/, "commitSha must be a full 40-character hex SHA");

const prNumber = z
  .number()
  .int()
  .positive()
  .max(2_147_483_647, "prNumber must be a GitHub PR number");

export const desktopPreviewManifestSchema = z
  .object({
    schemaVersion: z.literal(DESKTOP_PREVIEW_SCHEMA_VERSION),
    kind: z.literal("desktop-preview"),
    repository: z.string().trim().min(1),
    prNumber,
    commitSha,
    backendOrigin: httpsOrigin,
    oauthClientId: z.string().trim().min(16).max(2048),
  })
  .strict();

export type DesktopPreviewManifest = z.infer<
  typeof desktopPreviewManifestSchema
>;

export class DesktopPreviewConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "DesktopPreviewConfigError";
  }
}

/**
 * Parse and validate a preview manifest. Every failure mode — unknown schema
 * version, malformed identity, credential-bearing or non-HTTPS origin,
 * unexpected fields — throws `DesktopPreviewConfigError`, so a caller can never
 * fall back to a partially-valid deployment.
 */
export function parseDesktopPreviewManifest(
  raw: unknown,
): DesktopPreviewManifest {
  const result = desktopPreviewManifestSchema.safeParse(raw);
  if (!result.success) {
    const issues = result.error.issues
      .map((issue) => `${issue.path.join(".") || "(root)"}: ${issue.message}`)
      .join("; ");
    throw new DesktopPreviewConfigError(
      `Invalid desktop preview configuration: ${issues}`,
    );
  }
  return result.data;
}

/**
 * Application identity derived from the validated PR identity — the single
 * source for every surface that must agree: electron-builder metadata, the
 * URL scheme, the user-data directory, and the OAuth redirect URI. Never
 * derived from manifest-supplied strings, so PR-authored JSON cannot pick a
 * bundle id or a callback scheme.
 */
export interface DesktopPreviewIdentity {
  productName: string;
  appId: string;
  executableName: string;
  scheme: string;
  redirectUri: string;
  userDataDirName: string;
  artifactPrefix: string;
}

export function desktopPreviewIdentity(
  manifest: DesktopPreviewManifest,
): DesktopPreviewIdentity {
  const pr = manifest.prNumber;
  return {
    productName: `PostHog Preview PR ${pr}`,
    appId: `com.posthog.array.preview.pr${pr}`,
    executableName: `PostHog-Preview-PR-${pr}`,
    scheme: `posthog-code-preview-pr-${pr}`,
    redirectUri: `posthog-code-preview-pr-${pr}://callback`,
    userDataDirName: `posthog-code-preview-pr-${pr}`,
    artifactPrefix: `PostHog-Preview-PR-${pr}`,
  };
}

/**
 * Deployment identity pinned alongside preview sessions. A changed origin or
 * OAuth client id means the stored credentials belong to a different
 * deployment, and the client must discard them rather than present them to
 * the new one.
 */
export function desktopPreviewDeploymentId(
  manifest: DesktopPreviewManifest,
): string {
  return `${manifest.backendOrigin}|${manifest.oauthClientId}`;
}

/**
 * Fail-closed assertion for ordinary release builds: a preview manifest
 * present where a release build is being produced is a packaging bug that
 * would ship a production updater fed by preview configuration, so fail the
 * build rather than ignore the input.
 */
export function assertNoPreviewConfig(
  preview: DesktopPreviewManifest | null,
): void {
  if (preview) {
    throw new DesktopPreviewConfigError(
      "Preview configuration was supplied to a non-preview build; " +
        "refusing to produce a production-connected installer from preview input",
    );
  }
}

/**
 * Public metadata document served by the preview backend at
 * `/static/desktop-preview/deployment.json`. The installed client compares
 * `commitSha` against its baked-in manifest to detect that a push replaced
 * the backend behind the stable URL and a newer installer is required.
 */
export const PREVIEW_DEPLOYMENT_METADATA_PATH =
  "/static/desktop-preview/deployment.json";

export const previewDeploymentMetadataSchema = z
  .object({
    schemaVersion: z.literal(DESKTOP_PREVIEW_SCHEMA_VERSION),
    prNumber,
    commitSha,
    deploymentGeneration: z.number().int().nonnegative(),
  })
  .strict();

export type PreviewDeploymentMetadata = z.infer<
  typeof previewDeploymentMetadataSchema
>;
